<script setup>
import { computed, ref, watch } from 'vue'
import CourseCollection from '@/features/lingqLab/CourseCollection.vue'
import LearningPlaylists from '@/features/lingqLab/LearningPlaylists.vue'
import ImportLesson from '@/features/lingqLab/ImportLesson.vue'
import { safeSourceUrl } from '@/features/lingqLab/webImport'
import { lessons, dictionary, normalize, readState, STORAGE_KEY, statusLabels, isLearning, newWordPercent, scheduleReview } from '@/features/lingqLab/model'
const state = ref(readState())
const pendingLesson = ref(null)
function addToPlaylist(lesson) { pendingLesson.value = lesson; navigate('playlists') }
const reviewed = ref([])
const vocabQuery = ref(''), vocabStatus = ref('all'), dueOnly = ref(false), sentenceMode = ref(false), sentenceIndex = ref(0), settingsOpen = ref(false)
const sentences = computed(() => active.value.text.match(/[^.!?]+[.!?]+|[^.!?]+$/g)?.map(s => s.trim()).filter(Boolean) || [])
const vocabularyRows = computed(() => Object.entries(state.value.vocabulary).filter(([word, entry]) => (word + ' ' + entry.meaning).toLowerCase().includes(vocabQuery.value.toLowerCase()) && (vocabStatus.value === 'all' || String(entry.status) === vocabStatus.value) && (!dueOnly.value || (isLearning(entry) && entry.dueAt <= Date.now()))))
const view = ref('home'), query = ref(''), filter = ref('全部'), selected = ref(''), meaning = ref(''), message = ref(''), flipped = ref(false), reviewIndex = ref(0)
const activeId = ref(state.value.lastLesson)
const allLessons = computed(() => [...lessons, ...state.value.imports])
const active = computed(() => allLessons.value.find(l => l.id === activeId.value) || lessons[0])
const filtered = computed(() => allLessons.value.filter(l => (filter.value === '全部' || l.level === filter.value) && (l.title + l.topic + l.subtitle).toLowerCase().includes(query.value.toLowerCase())))
const savedWords = computed(() => Object.entries(state.value.vocabulary).filter(([,v]) => isLearning(v)))
const known = computed(() => Object.values(state.value.vocabulary).filter(v => v.status === 'known').length)
const reviewWords = computed(() => savedWords.value.filter(([word, entry]) => !reviewed.value.includes(word) && (!dueOnly.value || entry.dueAt <= Date.now())))
const card = computed(() => reviewWords.value[reviewIndex.value % Math.max(1, reviewWords.value.length)])
const paragraphs = computed(() => (sentenceMode.value ? sentences.value[sentenceIndex.value] || '' : active.value.text).split(/\n+/).filter(Boolean).map(p => p.match(/[A-Za-z]+(?:['’-][A-Za-z]+)*|[^A-Za-z]+/g)))
watch(state, () => { try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state.value)) } catch { message.value = '浏览器存储已满，本次更改无法在刷新后保存。' } }, { deep: true })
function navigate(next) { if (next === 'review') { reviewed.value = []; reviewIndex.value = 0; flipped.value = false } view.value = next; message.value = ''; window.scrollTo({ top: 0, behavior: 'smooth' }) }
function openLesson(lesson) { sentenceIndex.value = 0; activeId.value = lesson.id; state.value.lastLesson = lesson.id; selected.value = ''; navigate('reader'); window.xLearningAnalytics?.materialOpened('reading') }
function selectWord(word) { selected.value = normalize(word); meaning.value = state.value.vocabulary[selected.value]?.meaning || dictionary[selected.value] || ''; message.value = '' }
function saveWord(status) { if (!selected.value) return; state.value.vocabulary[selected.value] = { ...state.value.vocabulary[selected.value], meaning: meaning.value.trim(), status: status === 'learning' ? '1' : status, context: active.value.title, lessonId: active.value.id, dueAt: Date.now() }; message.value = status === 'known' ? '已标记掌握，所有课程同步更新。' : '已保存到词汇库，所有课程同步更新。' }
function importLesson(draft) { const lesson = { id: `import-${Date.now()}`, title: draft.title, subtitle: '你自己的阅读材料', text: draft.text, ...(safeSourceUrl(draft.sourceUrl) ? { sourceUrl: safeSourceUrl(draft.sourceUrl) } : {}), level: '自选', topic: '我的导入', icon: '↳', color: 'mint', minutes: Math.max(1, Math.ceil(draft.text.split(/\s+/).length / 180)) }; state.value.imports.push(lesson); openLesson(lesson) }

function review(remember) { if (!card.value) return; const reviewedWord = card.value[0]; state.value.vocabulary[reviewedWord] = scheduleReview(card.value[1], remember); reviewed.value.push(reviewedWord); reviewIndex.value = 0; state.value.reviewCount++; flipped.value = false }

function complete() { if (!state.value.completed.includes(active.value.id)) state.value.completed.push(active.value.id); navigate('library') }
</script>

<template>
  <div class="lab">
    <header class="lab-header">
      <button class="brand" @click="navigate('home')" aria-label="X Learning 首页"><span class="brand-icon">✳</span> X Learning<span class="lab-tag">LAB</span></button>
      <nav aria-label="主导航"><button :class="{current: view === 'library' || view === 'reader'}" @click="navigate('library')">探索内容</button><button :class="{current: view === 'review' || view === 'vocabulary'}" @click="navigate('vocabulary')">我的词汇 <span class="count">{{ savedWords.length }}</span></button><button @click="navigate('plans')">会员计划</button></nav>
      <button class="button green small" @click="navigate('import')">＋ 导入内容</button>
    </header>

    <main v-if="view === 'home'">
      <section class="hero">
        <div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="orbit orbit-three"></div>
        <div class="topic-node node-ai">✦ <span>Artificial intelligence</span></div><div class="topic-node node-science">↗ <span>A world of discoveries</span></div><div class="topic-node node-design">◷ <span>Ideas worth exploring</span></div>
        <div class="hero-inner"><p class="eyebrow">FOLLOW YOUR CURIOSITY</p><h1>让好奇心，<br>带你<span>学会英语。</span></h1><p class="hero-description">读懂前沿科技，收藏每个新发现。<br>在你真正感兴趣的内容里，让英语自然生长。</p><button class="button green hero-cta" @click="navigate('library')">开始探索，免费体验 <span>↗</span></button><p class="hero-note">无需注册 · 进度保存在当前浏览器</p><div class="interest-row"><span>AI</span><span>SCIENCE</span><span>DESIGN</span><span>YOUR NEXT IDEA</span></div></div>
      </section>
      <section class="intro section-width"><div><p class="eyebrow dark">LESS STUDYING. MORE DISCOVERING.</p><h2>不是又一篇课文，<br>是你想读懂的世界。</h2></div><p>从一篇好内容开始。遇见新词就点击，保存后在下一篇再次遇见。把碎片阅读，变成属于你的知识与语言积累。</p></section>
      <section class="steps section-width"><article><span>01 / DISCOVER</span><h3>找到让你好奇的内容</h3><p>人工智能、科学与设计，从兴趣出发。</p></article><article><span>02 / UNDERSTAND</span><h3>点击一个词，读懂更多</h3><p>添加自己的释义，建立专属词汇库。</p></article><article><span>03 / REMEMBER</span><h3>让每次遇见都有积累</h3><p>跨课程同步生词，用词卡巩固记忆。</p></article></section>
      <section class="featured section-width"><div class="section-heading"><div><p class="eyebrow dark">A LITTLE CURIOSITY GOES A LONG WAY</p><h2>今天，想了解什么？</h2></div><button class="text-button" @click="navigate('library')">探索全部内容 →</button></div><div class="lesson-grid"><button v-for="lesson in lessons" :key="lesson.id" class="lesson-card" @click="openLesson(lesson)"><div :class="['art', lesson.color]"><span>{{ lesson.icon }}</span><small>{{ lesson.topic }}</small></div><div class="card-copy"><p class="meta">{{ lesson.level }} · {{ lesson.minutes }} 分钟 · {{ newWordPercent(lesson.text, state.vocabulary) }}% 新词 · 原创短读</p><h3>{{ lesson.title }}</h3><p>{{ lesson.subtitle }}</p><span class="read-link">开始阅读 ↗</span></div></button></div></section>
      <section class="bottom-cta"><p class="eyebrow dark">MAKE IT YOUR OWN</p><h2>每一个新词，<br>都是看世界的新视角。</h2><button class="button navy" @click="navigate('library')">开启第一篇阅读 →</button></section>
    </main>

    <div v-else :class="['app-layout', {collapsed:state.sidebarCollapsed}]"><aside class="app-sidebar"><button class="sidebar-toggle" @click="state.sidebarCollapsed = !state.sidebarCollapsed" :aria-label="state.sidebarCollapsed ? '展开侧栏' : '折叠侧栏'">☰</button><button :class="{chosen:view==='library'||view==='collection'}" @click="navigate('library')">▦ <span>课程库</span></button><button :class="{chosen:view==='playlists'}" @click="navigate('playlists')">☷ <span>学习列表</span></button><button :class="{chosen:view==='vocabulary'||view==='review'}" @click="navigate('vocabulary')">Aa <span>词汇管理</span></button><button :class="{chosen:view==='import'}" @click="navigate('import')">＋ <span>导入内容</span></button><div class="sidebar-note">X LEARNING LAB<br>本地学习工作台</div></aside><main class="workspace section-width">
      <template v-if="view === 'library'">
        <div class="section-heading"><div><p class="eyebrow dark">YOUR CURIOSITY, YOUR CLASSROOM</p><h1>探索，让学习发生。</h1><p class="muted">挑一篇喜欢的内容，从今天的一点好奇开始。</p></div><button class="button navy" @click="openLesson(active)">继续阅读 →</button></div>
        <div class="library-insights"><button class="recent-learning" @click="openLesson(active)"><p class="eyebrow dark">PICK UP WHERE YOU LEFT OFF</p><span>最近学习</span><h3>{{ active.title }}</h3><small>{{ state.completed.includes(active.id) ? '已完成 · 再读一次' : '继续这一课' }} →</small></button><button class="collection-entry" @click="navigate('collection')"><div class="collection-entry-art">✦</div><div><p class="eyebrow dark">ORIGINAL COLLECTION</p><h3>Ideas for a curious world</h3><p>AI · 科技 · 科学 / 3 个课时</p><small>查看合集与学习进度 →</small></div></button></div>
        <div class="stats"><div><strong>{{ state.completed.length }}</strong><span>已读课程</span></div><div><strong>{{ savedWords.length }}</strong><span>正在学习的词</span></div><div><strong>{{ known }}</strong><span>已掌握词汇</span></div><div><strong>{{ state.reviewCount }}</strong><span>词卡复习次数</span></div></div>
        <div class="library-tools"><div class="filters"><button v-for="level in ['全部','B1','B2','自选']" :key="level" :class="{active: filter === level}" @click="filter = level">{{ level }}</button></div><input v-model="query" aria-label="搜索课程" placeholder="搜索内容或主题…"></div>
        <div class="lesson-grid"><button v-for="lesson in filtered" :key="lesson.id" class="lesson-card" @click="openLesson(lesson)"><div :class="['art', lesson.color]"><span>{{ lesson.icon }}</span><small>{{ lesson.topic }}</small></div><div class="card-copy"><p class="meta">{{ lesson.level }} · {{ lesson.minutes }} 分钟 · {{ newWordPercent(lesson.text, state.vocabulary) }}% 新词 <span v-if="state.completed.includes(lesson.id)">· 已读 ✓</span></p><h3>{{ lesson.title }}</h3><p>{{ lesson.subtitle }}</p><span class="read-link">开始阅读 ↗</span></div></button></div><p v-if="!filtered.length" class="empty">没有匹配的课程，试试其他关键词或导入自己的内容。</p>
      </template>
      <template v-else-if="view === 'collection'"><button class="text-button back" @click="navigate('library')">← 返回课程库</button><CourseCollection :lessons="lessons" :vocabulary="state.vocabulary" :completed="state.completed" @open="openLesson" @add="addToPlaylist" /></template>
      <template v-else-if="view === 'playlists'"><LearningPlaylists v-model:playlists="state.playlists" :lessons="allLessons" :pending-lesson="pendingLesson" @open="openLesson" @clear-pending="pendingLesson=null" /></template>
      <template v-else-if="view === 'reader'">
        <div class="reader-back-row"><button class="text-button back" @click="navigate('library')">← 返回内容库</button><button class="text-button" @click="addToPlaylist(active)">＋ 加入学习列表</button></div><div class="reader-layout"><article class="reading"><p class="eyebrow dark">{{ active.topic }} / {{ active.level }}</p><h1>{{ active.title }}</h1><p class="muted">{{ active.subtitle }}</p><a v-if="safeSourceUrl(active.sourceUrl)" :href="safeSourceUrl(active.sourceUrl)" target="_blank" rel="noopener noreferrer" class="reader-source">阅读原网页 ↗</a><div class="reader-tools"><div class="segmented"><button :class="{active:!sentenceMode}" @click="sentenceMode=false">全文模式</button><button :class="{active:sentenceMode}" @click="sentenceMode=true">逐句模式</button></div><button class="text-button" @click="settingsOpen=!settingsOpen" :aria-expanded="settingsOpen">Aa 阅读设置</button></div><div v-if="settingsOpen" class="reader-settings"><label>字号 {{ state.reader.size }}px<input type="range" min="16" max="32" v-model.number="state.reader.size"></label><label>主题<select v-model="state.reader.theme"><option value="paper">清爽白</option><option value="sepia">护眼米色</option><option value="night">夜间</option></select></label><label>字体<select v-model="state.reader.font"><option value="serif">衬线字体</option><option value="sans">无衬线字体</option></select></label></div><div class="reading-legend"><span><i class="blue-dot"></i>新词</span><span><i class="yellow-dot"></i>学习中</span><span>点击英文词开始学习</span></div><div :class="['passage',state.reader.theme]" :style="{fontSize:state.reader.size+'px',fontFamily:state.reader.font === 'serif' ? 'Georgia, serif' : 'Arial, sans-serif'}"><p v-for="(tokens, p) in paragraphs" :key="p"><template v-for="(token, i) in tokens" :key="i"><button v-if="/^[A-Za-z]/.test(token)" :class="['word', state.vocabulary[normalize(token)]?.status || 'new', {selected: selected === normalize(token)}]" @click="selectWord(token)">{{ token }}</button><span v-else>{{ token }}</span></template></p></div><div v-if="sentenceMode" class="sentence-controls"><button class="button outline" :disabled="sentenceIndex===0" @click="sentenceIndex--;selected=''">← 上一句</button><span>{{ sentenceIndex+1 }} / {{ sentences.length }}</span><button class="button outline" :disabled="sentenceIndex>=sentences.length-1" @click="sentenceIndex++;selected=''">下一句 →</button></div><label v-if="sentenceMode" class="sentence-slider">阅读进度<input type="range" min="0" :max="sentences.length-1" v-model.number="sentenceIndex" aria-label="句子进度"></label><button class="button navy" @click="complete">完成本篇阅读 ✓</button></article><aside :class="['word-panel', {'has-selection': selected}]"><template v-if="selected"><button class="close-word" aria-label="关闭词义面板" @click="selected = ''">×</button><p class="eyebrow dark">YOUR PERSONAL VOCABULARY</p><h2>{{ selected }}</h2><span class="status-label">{{ statusLabels[state.vocabulary[selected]?.status] || '新词' }}</span><label for="word-meaning">中文释义 / 你的笔记</label><textarea id="word-meaning" v-model="meaning" :placeholder="dictionary[selected] ? '' : '暂无示例释义，请填写自己的解释…'" rows="3"></textarea><p class="fine">内置少量演示释义，未连接在线词典。</p><button class="button green full" @click="saveWord('learning')">＋ 保存为学习词</button><div class="word-statuses"><button v-for="status in ['1','2','3','4']" :key="status" :class="{active:String(state.vocabulary[selected]?.status)===status}" @click="saveWord(status)">{{ statusLabels[status] }}</button></div><button class="text-button" @click="saveWord('ignored')">忽略此词</button><button class="button outline full" @click="saveWord('known')">已经认识这个词 ✓</button><p class="feedback" role="status">{{ message }}</p></template><template v-else><div class="panel-symbol">Aa</div><h2>一个词，新的发现。</h2><p class="muted">点击正文中的任意英文词，在这里查看或添加释义。</p><div class="panel-hint">蓝色 → 学习中 → 已掌握<br>你的词汇进度会跨课程同步。</div></template></aside></div>
      </template>
      <template v-else-if="view === 'import'"><ImportLesson :vocabulary="state.vocabulary" @import="importLesson" /></template>
      <template v-else-if="view === 'vocabulary'"><div class="section-heading"><div><p class="eyebrow dark">YOUR VOCABULARY</p><h1>每个新词，都有进步。</h1><p class="muted">{{ Object.keys(state.vocabulary).length }} 个词汇记录 · {{ known }} 个已掌握</p></div><button class="button green" @click="reviewIndex=0;flipped=false;navigate('review')">开始词卡复习 →</button></div><div class="vocab-filters"><input v-model="vocabQuery" aria-label="搜索词汇" placeholder="搜索单词或释义…"><select v-model="vocabStatus" aria-label="按词汇状态筛选"><option value="all">全部状态</option><option v-for="(label,status) in statusLabels" :key="status" :value="status">{{ label }}</option></select><label class="check-label"><input type="checkbox" v-model="dueOnly">仅到期复习</label></div><p class="fine">本地复习规则：新保存词立即到期；再学会安排在 10 分钟后；认识后提升一级，并按 2、4、8 天间隔安排，4 级再次认识后标记已掌握。</p><div class="vocab-table"><div class="vocab-table-head"><span>单词与释义</span><span>状态</span><span>来源 / 下次复习</span></div><div v-for="[word,entry] in vocabularyRows" :key="word" class="vocab-row"><div><strong>{{ word }}</strong><p>{{ entry.meaning || '未填写释义' }}</p></div><select v-model="entry.status" :aria-label="word+' 的状态'"><option v-for="(label,status) in statusLabels" :key="status" :value="status">{{ label }}</option></select><div class="vocab-context">{{ entry.context }}<small>{{ isLearning(entry) ? (entry.dueAt <= Date.now() ? '已到期' : new Date(entry.dueAt).toLocaleDateString('zh-CN')) : '无需复习' }}</small></div></div></div><div v-if="!vocabularyRows.length" class="empty"><h2>这里还没有匹配的词。</h2><p>调整筛选，或在阅读时保存你想记住的词。</p><button class="button navy" @click="navigate('library')">去阅读 →</button></div></template>
      <template v-else-if="view === 'review'"><div class="review-shell"><p class="eyebrow dark">LITTLE BY LITTLE, IT STICKS</p><h1>再遇见，就更熟悉。</h1><p class="muted">{{ reviewWords.length }} 个待复习词 · 已复习 {{ state.reviewCount }} 次</p><template v-if="card"><button class="flashcard" @click="flipped = !flipped" :aria-label="flipped ? '显示英文' : '翻面查看释义'"><span>{{ flipped ? 'MEANING' : 'YOUR WORD' }}</span><strong>{{ flipped ? card[1].meaning || '未填写释义，可在阅读器中补充' : card[0] }}</strong><small>{{ flipped ? card[1].context : '点击卡片，查看释义 ↻' }}</small></button><div class="review-actions"><button class="button outline" @click="review(false)">再学一次 ↻</button><button class="button green" @click="review(true)">认识了 ✓</button></div></template><div v-else class="empty"><div class="panel-symbol">✦</div><h2>好奇心，是最好的起点。</h2><p>当前没有待复习词汇，阅读时把想学的词保存下来吧。</p><button class="button green" @click="navigate('library')">去发现新内容 →</button></div></div></template>
      <template v-else-if="view === 'plans'"><div class="plans-title"><p class="eyebrow dark">A PLAN FOR EVERY CURIOUS MIND</p><h1>为你的好奇心，留一点空间。</h1><p class="muted">以下仅为产品套餐演示，不会收款；当前演示功能全部开放。</p></div><div class="plan-grid"><article v-for="(plan, i) in [{name:'Explore',price:'免费',desc:'从第一篇阅读开始',features:['浏览原创课程','点击词汇与个人笔记','本地学习进度']},{name:'Curious',price:'¥39',desc:'持续积累，形成习惯',features:['设想：不限量个人导入','设想：跨设备词汇同步','设想：更多复习方式']},{name:'Deep Dive',price:'¥69',desc:'深入内容背后的世界',features:['设想：AI 内容解释','设想：音频转写','设想：个性化学习反馈']}]" :key="plan.name" :class="['plan', {recommended:i===1}]"><p class="eyebrow dark">{{ plan.name }}</p><h2>{{ plan.price }}<small v-if="i"> / 月</small></h2><p class="muted">{{ plan.desc }}</p><ul><li v-for="feature in plan.features" :key="feature">✓ {{ feature }}</li></ul><button class="button full" :class="i===1?'green':'outline'" @click="i === 0 ? navigate('library') : message = '这是套餐设计演示，尚未开放购买。你可以免费体验所有已实现功能。'">{{ i ? '了解演示套餐' : '开始免费体验' }}</button></article></div><p class="feedback centered" role="status">{{ message }}</p></template>
    </main></div>
    <footer class="lab-footer"><span class="brand">✳ X Learning</span><p>Learn something new. See the world differently.</p><span>公开页面参考实验 · 原创示例内容 · 本地演示</span></footer>
  </div>
